  const fmt=n=>{const v=[['0',0],['1',1],['−1',-1],['1/2',.5],['−1/2',-.5],['√2/2',Math.SQRT1_2],['−√2/2',-Math.SQRT1_2],['√3/2',Math.sqrt(3)/2],['−√3/2',-Math.sqrt(3)/2]].find(([,x])=>Math.abs(n-x)<.012);if(v)return v[0];let bestN=Math.round(n),bestD=1,err=Infinity;for(let d=1;d<=24;d++){const a=Math.round(n*d),e=Math.abs(n-a/d);if(e<err){bestN=a;bestD=d;err=e;}}return err<.012?`${bestN<0?'−':''}${Math.abs(bestN)}/${bestD}`:String(n.toFixed(2)).replace('-', '−');};
  const RAD_TEXT={0:'0',30:'π/6',45:'π/4',60:'π/3',90:'π/2',120:'2π/3',135:'3π/4',150:'5π/6',180:'π',210:'7π/6',225:'5π/4',240:'4π/3',270:'3π/2',300:'5π/3',315:'7π/4',330:'11π/6'};
