  // All audio is generated locally with Web Audio; no sound assets or network calls.
  function initAudio(){if(!state.audio){const AC=window.AudioContext||window.webkitAudioContext;if(!AC){state.sound=false;return;}state.audio=new AC();for(const [i,f] of [55,82.4].entries()){const osc=state.audio.createOscillator(),gain=state.audio.createGain();osc.type='sine';osc.frequency.value=f;gain.gain.value=0;osc.connect(gain);gain.connect(state.audio.destination);osc.start();state.drone.push({osc,gain,base:i===0?.012:.006});}}if(state.audio.state==='suspended')state.audio.resume();syncDrone();}
  function syncDrone(){if(!state.audio)return;for(const d of state.drone)d.gain.gain.setTargetAtTime(state.sound?d.base:0,state.audio.currentTime,.4);}
  function musicVoice(freq,duration,volume,type='triangle'){if(!state.sound||!state.audio)return;const ac=state.audio,osc=ac.createOscillator(),gain=ac.createGain();osc.type=type;osc.frequency.setValueAtTime(freq,ac.currentTime);gain.gain.setValueAtTime(.0001,ac.currentTime);gain.gain.exponentialRampToValueAtTime(volume,ac.currentTime+.08);gain.gain.exponentialRampToValueAtTime(.0001,ac.currentTime+duration);osc.connect(gain);gain.connect(ac.destination);osc.start();osc.stop(ac.currentTime+duration+.03);}
  function updateMusic(dt){if(!state.audio||!state.sound)return;state.musicClock+=dt;if(state.musicClock<.34)return;state.musicClock-=.34;const roots=[220,196,174.61,146.83],pattern=[0,7,12,7,3,10,7,5,0,7,14,12,5,10,7,3],root=roots[state.stage]||roots[0],step=state.musicStep++%pattern.length;musicVoice(root*Math.pow(2,pattern[step]/12),.32,.006,'triangle');if(step%4===0)musicVoice(root/2,.72,.012,'sine');if(step===8||step===0)musicVoice(root*2,.24,.0025,'sine');}
  function setMissionAudio(){if(!state.audio)return;const notes=[[55,82.4],[62,92.5],[73.4,110],[41.2,61.7]][state.stage];state.drone.forEach((d,i)=>d.osc.frequency.setTargetAtTime(notes[i],state.audio.currentTime,.8));}
  function tone(freq,duration=.1,type='sine',volume=.035,slide=0){if(!state.sound||!state.audio)return;const ac=state.audio,osc=ac.createOscillator(),gain=ac.createGain();osc.type=type;osc.frequency.setValueAtTime(freq,ac.currentTime);if(slide)osc.frequency.exponentialRampToValueAtTime(Math.max(35,freq+slide),ac.currentTime+duration);gain.gain.setValueAtTime(.0001,ac.currentTime);gain.gain.exponentialRampToValueAtTime(volume,ac.currentTime+.012);gain.gain.exponentialRampToValueAtTime(.0001,ac.currentTime+duration);osc.connect(gain);gain.connect(ac.destination);osc.start();osc.stop(ac.currentTime+duration+.02);}
  function sfx(kind){if(!state.sound)return;switch(kind){case'fire':tone(610,.11,'sawtooth',.04,-330);tone(1180,.055,'triangle',.018,-620);break;case'explode':tone(155,.32,'sawtooth',.085,-120);tone(72,.38,'triangle',.065,-35);tone(520,.12,'sine',.03,-410);break;case'hit':tone(190,.18,'triangle',.07,-105);tone(480,.1,'sine',.025,170);break;case'shield':tone(270,.2,'sine',.055,390);break;case'damage':tone(125,.34,'sawtooth',.06,-70);break;case'clear':tone(420,.14,'triangle',.05,160);setTimeout(()=>tone(630,.19,'triangle',.04,210),100);break;case'boss':tone(72,.65,'sawtooth',.05,33);break;case'scan':tone(730,.2,'sine',.045,-520);break;}}
