  function angleQuadrant(angle){return angle<=90?1:angle<=180?2:angle<=270?3:4;}
  function valueQuadrant(key){return key.startsWith('−')?2:1;}
  function coordinateKey(angle,coordinate){const p=xy(angle),value=coordinate==='x'?p.x:p.y;return SIN_VALUES.reduce((best,v)=>Math.abs(v.value-value)<Math.abs(best.value-value)?v:best,SIN_VALUES[0]).key;}
  function valueWeaponName(key){return ({'1/2':'ION','√2/2':'PRISM','√3/2':'NOVA','0':'NULL','−1/2':'UMBRA','−√2/2':'ECLIPSE','−√3/2':'VOID','1':'ZENITH','−1':'NADIR'})[key]||'RELIC';}
  function unlockTrainingWeapons(){for(const v of SIN_VALUES){if(valueQuadrant(v.key)>state.unlockedQuadrants||state.weapons.some(w=>w.key===v.key))continue;state.weapons.push({key:v.key,value:v.value,name:valueWeaponName(v.key),color:WEAPON_COLORS[SIN_VALUES.indexOf(v)]});}state.weapons.sort((a,b)=>SIN_VALUES.findIndex(v=>v.key===a.key)-SIN_VALUES.findIndex(v=>v.key===b.key));}
  function shuffle(list){for(let i=list.length-1;i>0;i--){const j=(Math.random()*(i+1))|0;[list[i],list[j]]=[list[j],list[i]];}return list;}
  function shuffleWeaponButtons(){state.angleButtonOrder=shuffle([...ANGLE_WEAPONS]);state.valueButtonOrder=shuffle([...SIN_VALUES]);$('angle-weapons').dataset.signature='';$('value-weapons').dataset.signature='';}
  function renderWeapons(){const angles=$('angle-weapons'),values=$('value-weapons'),sig=state.weapons.map(w=>w.key).join('|')+`|Q${state.unlockedQuadrants}`;if(angles.dataset.signature!==sig){angles.dataset.signature=sig;angles.innerHTML=state.angleButtonOrder.map(a=>{const locked=angleQuadrant(a)>state.unlockedQuadrants;return `<button class="weapon-card angle-card ${locked?'locked':''}" data-angle-weapon="${a}" style="--weapon:#68dfff" aria-label="${locked?'ล็อกมุม':'มุม '+angleText(a)}" ${locked?'disabled':''}><b>${angleText(a)}</b></button>`;}).join('');}if(values.dataset.signature!==sig){values.dataset.signature=sig;values.innerHTML=state.valueButtonOrder.map(v=>{const i=SIN_VALUES.indexOf(v),index=state.weapons.findIndex(w=>w.key===v.key),owned=index>=0,locked=valueQuadrant(v.key)>state.unlockedQuadrants||!owned;return `<button class="weapon-card value-card ${locked?'locked':''}" data-weapon="${index}" style="--weapon:${WEAPON_COLORS[i]}" aria-label="${locked?'ล็อกค่า':'ค่า '+v.key}" ${locked?'disabled':''}><b>${v.key}</b></button>`;}).join('');}angles.querySelectorAll('.weapon-card').forEach(b=>{const selected=Number(b.dataset.angleWeapon)===state.activeAngleWeapon;b.classList.toggle('selected',state.activeWeaponType==='angle'&&selected);b.querySelector('b').textContent=angleText(Number(b.dataset.angleWeapon));});values.querySelectorAll('.weapon-card').forEach(b=>b.classList.toggle('selected',state.activeWeaponType==='value'&&Number(b.dataset.weapon)===state.activeWeapon));}
  $('weapon-rack').addEventListener('click',e=>{const a=e.target.closest('[data-angle-weapon]'),v=e.target.closest('[data-weapon]');if(a){fire('angle',Number(a.dataset.angleWeapon));}else if(v){fire('value',Number(v.dataset.weapon));}});
  document.querySelectorAll('[data-unit]').forEach(b=>b.addEventListener('click',()=>{state.unit=b.dataset.unit;document.querySelectorAll('[data-unit]').forEach(x=>x.classList.toggle('active',x===b));updateHUD();}));
  document.querySelectorAll('[data-difficulty]').forEach(b=>b.addEventListener('click',()=>{state.difficulty=b.dataset.difficulty;state.maxPlayerHp=DIFFICULTIES[state.difficulty].playerHp;state.playerHp=state.maxPlayerHp;document.querySelectorAll('[data-difficulty]').forEach(x=>x.classList.toggle('active',x===b));feed(`THREAT LEVEL · ${DIFFICULTIES[state.difficulty].label}`);updateHUD();}));

  function lessonGraphic(step){const concepts=['UNIT CIRCLE · START AT +X','SPECIAL ANGLES · ORBIT BEACONS','ANGLE → VALUE · PROJECT x / y','VALUE → ANGLE · DECODE SIGNAL','QUADRANT II · NEGATIVE x','QUADRANT III · BOTH NEGATIVE','QUADRANT IV · NEGATIVE y','FLIGHT CERTIFICATION · TWO HITS'];const x=(step%4)*(100/3),y=step<4?0:100;return `<div class="lesson-art-scene" style="--scene-position:${x}% ${y}%" role="img" aria-label="${TUTORIAL[step].title}"></div><div class="lesson-art-caption"><small>FLIGHT SCHOOL · STEP ${String(step+1).padStart(2,'0')} / ${TUTORIAL.length}</small><b>${concepts[step]}</b><span>MISSION VISUAL // DEGREE CORE ACADEMY</span></div>`;}
  function renderTutorial(){state.mode='tutorial';state.trainingDummy=false;const t=TUTORIAL[state.tutorialStep];$('overlay-title').innerHTML=`${t.title}<span>UNIT CIRCLE ACADEMY · ${state.unit.toUpperCase()} / STEP ${state.tutorialStep+1} OF ${TUTORIAL.length}</span>`;$('lesson-art').hidden=false;$('lesson-art').innerHTML=lessonGraphic(state.tutorialStep);$('overlay-copy').innerHTML=`${formatUnits(t.copy)}<br><br><b style="font:11px Consolas,monospace;color:#ffd27b">${formatUnits(t.formula)}</b><br><br>เริ่มโจทย์ฝึกเพื่อทดลองเลือกอาวุธและยิงเป้าจริง` ;box.querySelector('.brief-emblem').innerHTML='◎<span>✦</span>';box.querySelector('.brief-controls').innerHTML='<span>Angle Cannon / Value Cannon</span><span><kbd>SPACE</kbd> ยิงอาวุธที่เลือก</span><span><kbd>H</kbd> คำใบ้</span>';const launch=$('launch');launch.hidden=false;launch.querySelector('span').textContent='เริ่มบทฝึกนี้ ↗';launch.onclick=beginTrainingStep;state.aimAngle=TUTORIAL[state.tutorialStep].angle||45;state.angle=state.aimAngle;state.trainingTarget=135;state.trainingHits=0;overlay.classList.remove('hidden');updateHUD();}
  function beginTrainingStep(){state.mode='tutorial';state.trainingDummy=true;const drills=[{angle:45,prompt:'angle',coordinate:'x',key:'√2/2'},{angle:60,prompt:'angle',coordinate:'y',key:'√3/2'},{angle:60,prompt:'value',coordinate:'y',solution:'angle',key:'√3/2'},{angle:45,prompt:'value',coordinate:'x',solution:'angle',key:'√2/2'}],drill=drills[state.tutorialStep];shuffleWeaponButtons();state.unlockedQuadrants=1;unlockTrainingWeapons();const weapon=state.weapons.find(w=>w.key===drill.key)||state.weapons[0],angle=drill.angle,prompt=drill.prompt,solutionType=drill.solution||(prompt==='angle'?'value':'angle');state.trainingTarget=angle;state.enemies=[{id:'training',angle,r:orbitR+118,speed:0,kind:state.tutorialStep>=4?'shield-drone':'scout',size:25,spin:0,age:0,passed:false,open:true,value:weapon.value,valueKey:weapon.key,xKey:coordinateKey(angle,'x'),yKey:coordinateKey(angle,'y'),hp:state.tutorialStep===7?2:1,maxHp:state.tutorialStep===7?2:1,prompt,solutionType,mathName:drill.coordinate==='x'?'cos':'sin',coordinate:drill.coordinate}];state.trainingCoordinate=drill.coordinate;state.trainingValue=weapon.key;state.trainingMatchType=solutionType;state.activeWeaponType=state.trainingMatchType;state.activeAngleWeapon=angle;state.activeWeapon=Math.max(0,state.weapons.findIndex(w=>w.key===weapon.key));overlay.classList.add('hidden');$('weapon-rack').hidden=false;feed(`TRAINING STEP ${state.tutorialStep+1} · MATCH TARGET ${solutionType==='angle'?angleText(angle):weapon.key}`);updateHUD();updateTelemetry();}
  function completeTrainingStep(){state.trainingDummy=false;state.mode='tutorial';const next=state.tutorialStep<TUTORIAL.length-1;const angle=angleText(state.trainingTarget),value=state.trainingValue,coordinate=state.trainingCoordinate||'y';$('overlay-title').innerHTML=`STEP ${state.tutorialStep+1} COMPLETE<span>WEAPON MATCH CONFIRMED</span>`;$('overlay-copy').textContent=`ถูกต้อง! เป้าหมายอยู่ที่ ${angle} ${state.trainingMatchType==='angle'?`เห็น ${coordinate} = ${value} แล้วเลือก Angle Cannon ${angle}`:`จากมุม ${angle} ได้ ${coordinate} = ${value} แล้วเลือก Value Cannon`} แล้วโจมตีสำเร็จ${!next?' คุณผ่านพื้นฐาน Q1 แล้ว และพร้อมเรียนรู้การสะท้อนไป Q2 ในด่านถัดไป':''}`;box.querySelector('.brief-controls').innerHTML='<span>WEAPON LOCK · CONFIRMED</span><span>MISSION XP +100</span>';state.score+=100;state.trainingHits++;$('lesson-art').hidden=true;$('launch').hidden=false;$('launch').querySelector('span').textContent=next?'ขั้นต่อไป ↗':'ดูภารกิจแรก ↗';$('launch').onclick=()=>{if(next){state.tutorialStep++;renderTutorial();}else{state.trainingDummy=false;state.unlockedQuadrants=1;unlockTrainingWeapons();state.energy=100;missionBrief(0);}};overlay.classList.remove('hidden');updateHUD();}
  function beginSafePractice(){state.mode='tutorial';state.trainingDummy=true;state.trainingTarget=45;state.enemies=[];state.bullets=[];overlay.classList.add('hidden');$('deploy-button').hidden=false;feed('ACADEMY SANDBOX · NO HULL LOSS · ENTER TO DEPLOY');updateHUD();}
