  function missionBrief(index){state.stage=index;state.mode='brief';$('lesson-art').hidden=true;const m=STAGES[index];$('overlay-title').innerHTML=`${m.title}<span>${m.kicker} · RUN ${state.clearedMissions+1}</span>`;$('overlay-copy').textContent=m.story;$('upgrade-choices').hidden=true;$('run-actions').hidden=true;$('launch').hidden=false;$('retry-wave').hidden=true;$('launch').querySelector('span').textContent='เข้าสู่ภารกิจ ↗';box.querySelector('.brief-emblem').innerHTML='✦';box.querySelector('.brief-controls').innerHTML=`<span>OBJECTIVE · ${m.objectives[0]}</span><span>PILOT ${state.playerHp}/${state.maxPlayerHp} · CORE ${state.hull}/3</span><span>UNIT · ${state.unit.toUpperCase()} · ${DIFFICULTIES[state.difficulty].label} · RELICS ${state.relics.length}</span>`;$('launch').onclick=()=>startStage(index);overlay.classList.remove('hidden');updateHUD();}
  function startStage(index,practice=false){shuffleWeaponButtons();state.stage=index;state.unlockedQuadrants=index===0?1:index===1?2:4;unlockTrainingWeapons();state.progress=0;state.streak=0;state.enemies=[];state.bullets=[];state.enemyShots=[];state.particles=[];state.spawn=1.9+Math.random()*1.5;state.bossHits=0;state.bossPhase=0;state.waveCue=-1;assignBossWeakpoint();state.bossCycle=0;state.scanner=0;state.scannerCooldown=0;state.hintLevel=0;state.practice=practice;state.trainingDummy=false;state.mode='playing';state.keys.cooldown=0;state.stats.stageShots=0;state.stats.stageLocks=0;state.gameTimer=0;state.stats.started=state.stats.started||Date.now();$('deploy-button').hidden=true;overlay.classList.add('hidden');$('pause').style.visibility='visible';setMissionAudio();updateHUD();updateTelemetry();feed(practice?'PRACTICE MISSION · NO TIME LIMIT':index===3?'DEGREE OVERLORD SIGNATURE DETECTED':'DEFENSE GRID ACTIVE');if(index===3)sfx('boss');else sfx('clear');}
  function currentWave(){return state.stage===3?Math.floor(state.bossHits/3):Math.min(2,Math.floor(state.progress/4));}
  function enemySpawnDelay(wave){const min=3.2-wave*.7,max=4.1-wave*.7;return(min+Math.random()*(max-min))*DIFFICULTIES[state.difficulty].spawnInterval;}
  function pick(list,index){return list[((index%list.length)+list.length)%list.length];}
  function assignBossWeakpoint(){const w=state.weapons[(Math.random()*state.weapons.length)|0],d=SIN_VALUES.find(v=>v.key===w.key)||SIN_VALUES[0];state.bossAngle=d.angles[(Math.random()*d.angles.length)|0];state.bossCoordinate=Math.random()<.5?'x':'y';state.bossValueKey=coordinateKey(state.bossAngle,state.bossCoordinate);state.bossXKey=coordinateKey(state.bossAngle,'x');state.bossYKey=coordinateKey(state.bossAngle,'y');state.bossValue=SIN_VALUES.find(v=>v.key===state.bossValueKey)?.value||0;state.bossPrompt=Math.random()<.5?'angle':'value';state.bossBaseAngle=state.bossAngle;}
  function spawnEnemy(){const stage=currStage(),wave=currentWave(),i=state.progress%4;let angle,type='scout';
    if(stage.kind==='combat'){if(wave===0){angle=pick([0,90,180,270],i);type='scout';}else if(wave===1){angle=pick([30,45,60,45],i);type='scout';}else{angle=pick([45,45,225,315],i);type='asteroid';}}
    else if(stage.kind==='shield'){if(wave===0){angle=pick([45,135,225,315],i);type='bomber';}else if(wave===1){angle=45+Math.random()*90;type='zigzag';}else{angle=pick([135,150,120,225],i);type='bomber';}}
    else{if(wave===0){angle=pick([135,225,315,45],i);type='mirror';}else if(wave===1){angle=pick([45,135,225,315],i);type='mirror';}else{angle=pick([30,150,30,150],i);type='shield-drone';}}
    const levelAngles=stage.kind==='combat'?[0,30,45,60,90]:stage.kind==='shield'?[0,30,45,60,90,120,135,150,180]:SPECIAL;angle=pick(levelAngles,(Math.random()*levelAngles.length)|0);const coordinate=Math.random()<.5?'x':'y',valueKey=coordinateKey(angle,coordinate),definition=SIN_VALUES.find(v=>v.key===valueKey)||SIN_VALUES[0],weapon=state.weapons.find(w=>w.key===valueKey)||START_WEAPONS[0],prompt=Math.random()<.5?'angle':'value',solutionType=prompt==='angle'?'value':'angle';const difficulty=state.clearedMissions,diff=DIFFICULTIES[state.difficulty],waveHp=wave>0?1:0,hp=(type==='shield-drone'?3:type==='bomber'||type==='asteroid'||type==='mirror'?2:1)+waveHp+(difficulty>1?1:0)+diff.armorBonus;const enemy={id:Math.random().toString(36).slice(2),angle,r:screenSpawnRadius(angle,48+Math.random()*28),speed:(21+Math.random()*9)*.75,maxSpeed:(68+Math.random()*17+difficulty*9+wave*12)*diff.enemySpeed*.75,accel:(7+Math.random()*3+wave*1.4+difficulty)*.75,kind:type,size:type==='asteroid'?23+Math.random()*8:17+Math.random()*7,spin:Math.random()*TAU,age:0,passed:false,canShoot:['bomber','mirror','shield-drone','orb','asteroid'].includes(type),fireCooldown:2.7+Math.random()*3.2,open:type!=='shield-drone'||state.upgrades.has('phase_key'),mirrorAngle:wrap(180-angle),baseAngle:angle,value:definition.value,valueKey,xKey:coordinateKey(angle,'x'),yKey:coordinateKey(angle,'y'),coordinate,color:weapon.color,hp,maxHp:hp,prompt,solutionType,mathName:coordinate==='x'?'cos':'sin',damage:type==='bomber'||type==='orb'?2:1};state.enemies.push(enemy);}

